* { box-sizing: border-box; }
body {
  min-width: 360px; min-height: 100vh; margin: 0; padding: 28px 16px;
  display: grid; place-items: center; color: #26334a; background: #dce9e7;
  font: 16px/1.5 system-ui, sans-serif;
}
.card {
  width: min(100%, 420px); padding: 30px; text-align: center; background: #fffdf5;
  border: 4px solid #26334a; box-shadow: 8px 8px 0 #26334a;
}
.pixel-art {
  width: 92px; height: 92px; margin: 0 auto 18px; display: grid; place-items: center;
  color: #fffdf5; background: #ed8065; border: 4px solid #26334a;
  box-shadow: 4px 4px 0 #26334a; font-size: 46px; image-rendering: pixelated;
}
.eyebrow, .bio-label { font-weight: 800; letter-spacing: .12em; font-size: 14px; }
.eyebrow { margin: 0 0 4px; color: #65716c; }
h1 { margin: 0; font-size: clamp(28px, 8vw, 36px); line-height: 1.2; }
.title { margin: 8px 0 20px; color: #65716c; }
.editable { border-radius: 2px; cursor: text; }
.editable:hover { background: #f4edcf; }
.editable:focus { outline: 3px solid #ed8065; outline-offset: 3px; background: #fff4dc; }
.divider { height: 4px; margin: 0 0 18px; background: #26334a; }
.bio-label { display: flex; justify-content: space-between; color: #65716c; }
#counter { letter-spacing: normal; font-weight: 600; }
.bio { min-height: 76px; margin: 8px 0 20px; padding: 8px; text-align: left; overflow-wrap: anywhere; }
.actions { display: flex; gap: 10px; }
button { flex: 1; min-height: 48px; padding: 10px 12px; border: 3px solid #26334a; color: #fffdf5; background: #26334a; font: inherit; font-weight: 750; cursor: pointer; }
button:hover { background: #42536e; }
button:focus-visible { outline: 3px solid #ed8065; outline-offset: 3px; }
button:active { transform: translate(2px, 2px); box-shadow: inset 2px 2px #26334a; }
button.secondary { color: #26334a; background: transparent; }
button.secondary:hover { background: #f4edcf; }
.status { min-height: 24px; margin: 12px 0 0; color: #32725f; font-weight: 750; }
.hint { margin: 2px 0 0; color: #65716c; font-size: 14px; }
@media (max-width: 400px) { .card { padding: 24px 18px; } }

const bio = document.querySelector('#bio');
const fields = [...document.querySelectorAll('.editable')];
const counter = document.querySelector('#counter');
const status = document.querySelector('#status');
const limit = 120;
let saved = fields.map(field => field.innerText);

function updateCounter() {
  const chars = Array.from(bio.innerText);
  if (chars.length > limit) {
    bio.innerText = chars.slice(0, limit).join('');
    const selection = window.getSelection();
    const range = document.createRange();
    range.selectNodeContents(bio);
    range.collapse(false);
    selection.removeAllRanges();
    selection.addRange(range);
  }
  counter.textContent = `${Array.from(bio.innerText).length}/${limit}`;
}

fields.forEach(field => {
  field.addEventListener('input', () => {
    status.textContent = '';
    if (field === bio) updateCounter();
  });
  field.addEventListener('keydown', event => {
    if (event.key === 'Enter' && field !== bio) {
      event.preventDefault();
      field.blur();
    }
  });
});

document.querySelector('#save').addEventListener('click', () => {
  saved = fields.map(field => field.innerText);
  status.textContent = 'Saved';
});

document.querySelector('#cancel').addEventListener('click', () => {
  fields.forEach((field, index) => { field.innerText = saved[index]; });
  updateCounter();
  status.textContent = 'Changes canceled';
});

updateCounter();
